const locationMarkers = []
const heights = { world: 640, nautilus: 220, 'route-one': 1573, 'route-two': 903 }
function location(slug, map, name, description, x, yTop, iconType = 'landmark', linked = null, artwork = 'plate-1') {
  locationMarkers.push({ ...base, id: locId(slug), mapLayerId: mapId(map), linkedMapLayerId: linked ? mapId(linked) : null, name, description, x, y: heights[map] - yTop, iconType, tags: [], factionId: null, imageId: imageId(artwork) })
}

function geo(slug, name, description, lon, lat, iconType = 'ocean', artwork = 'plate-1', linked = null) {
  const x = ((lon + 180) / 360) * 1280
  const yTop = ((90 - lat) / 180) * 640
  location(slug, 'world', name, description, Math.round(x), Math.round(yTop), iconType, linked, artwork)
}

