if (chapterDefs.length !== 46) throw new Error(`Expected 46 chapters, found ${chapterDefs.length}`)
const chapters = chapterDefs.map((row, index) => ({ ...base, id: chId(index + 1), timelineId, number: index + 1, title: row.title, summary: row.summary, notes: index < 23 ? 'Part One' : 'Part Two', status: 'final' }))
const epoch = Date.UTC(1866, 0, 1)
const eventDefs = chapterDefs.flatMap((row, chapterIndex) => row.beats.map((entry, beatIndex) => ({ ...entry, chapter: chapterIndex + 1, beatIndex })))
const events = eventDefs.map((entry, index) => {
  const at = (Date.parse(entry.date) - epoch) / 86_400_000
  const prevAt = index ? (Date.parse(eventDefs[index - 1].date) - epoch) / 86_400_000 : at
  return { ...base, id: id('event', String(index + 1).padStart(3, '0')), chapterId: chId(entry.chapter), timelineId, title: entry.title, description: entry.description, locationMarkerId: locId(entry.loc), involvedCharacterIds: Object.keys(entry.states).map(charId), mentionedCharacterIds: entry.mentioned.map(charId), involvedItemIds: entry.items.map(itemId), tags: [`part-${entry.chapter <= 23 ? 'one' : 'two'}`, `chapter-${entry.chapter}`], threadIds: entry.threads.map(threadId), motifIds: entry.motifs.map(motifId), sortOrder: index, travelDays: index ? Math.max(0, at - prevAt) : 0, inWorldTime: Math.floor(at), tension: entry.tension, structureBeat: entry.structureBeat, status: 'final', povCharacterId: entry.pov ? charId(entry.pov) : null, isFlashback: false }
})
const eventByTitle = new Map(events.map(row => [row.title, row]))
const findEvent = title => { const row = eventByTitle.get(title); if (!row) throw new Error(`Unknown event ${title}`); return row.id }
const characterSnapshots = []
eventDefs.forEach((entry, index) => {
  const eventRow = events[index]
  const locationRow = locationMarkers.find(row => row.id === eventRow.locationMarkerId)
  const sortKey = entry.chapter + eventRow.sortOrder / 1_000_000
  for (const [slug, statusNotes] of Object.entries(entry.states)) characterSnapshots.push({ ...base, id: id('snapshot', `${index + 1}-${slug}`), characterId: charId(slug), eventId: eventRow.id, isAlive: !entry.dead.includes(slug), currentLocationMarkerId: eventRow.locationMarkerId, currentMapLayerId: locationRow.mapLayerId, inventoryItemIds: [], inventoryNotes: '', travelModeId: null, sortKey, statusNotes })
})

