const data = {
  version: 16, type: 'worldbreaker-export', exportedAt: now,
  world: { id: worldId, name: 'Twenty Thousand Leagues Under the Seas', description: 'Professor Pierre Aronnax, Conseil, and harpooner Ned Land are cast aboard the Nautilus while hunting a supposed sea monster. Under Captain Nemo’s command, captivity becomes a voyage through the world’s oceans, where scientific wonder, technological independence, compassion, and vengeance become impossible to separate.', coverImageId: imageId('cover'), theme: 'theme-scifi', readingMode: true, createdAt: now, updatedAt: now, continuityStaleThreshold: 5, calendar: { startYear: 1866, yearSuffix: '', months }, wordTarget: null },
  mapLayers, locationMarkers, characters, items, characterSnapshots, characterMovements: [], itemPlacements, locationSnapshots: [], itemSnapshots: [], relationships, relationshipSnapshots: [],
  timelines: [{ id: timelineId, worldId, name: 'The Voyage beneath the Seas', description: 'One continuous chronology from the first 1866 sightings through the 1867 expedition and the captives’ 1868 escape.', color: '#3f8291', dayOffset: 0, createdAt: now }],
  chapters, events, blobs, travelModes: [], timelineRelationships: [], crossTimelineArtifacts: [], mapRoutes, mapRegions: [], mapRegionSnapshots: [], mapAnnotations: [],
  loreCategories, lorePages, factions, factionMemberships, factionRelationships, knowledgeFacts, knowledgeReveals, characterGoals, sceneTexts: [], plotThreads, motifs, continuitySuppressions: [], writingLogs: [], sceneRevisions: [],
}

const allIds = new Map()
for (const [collection, rows] of Object.entries(data)) if (Array.isArray(rows)) for (const row of rows) if (row.id) { if (allIds.has(row.id)) throw new Error(`Duplicate ${row.id}`); allIds.set(row.id, collection) }
const assertRef = (value, rows, label) => { if (value != null && !rows.some(row => row.id === value)) throw new Error(`${label}: ${value}`) }
events.forEach(row => { assertRef(row.chapterId, chapters, `${row.id}.chapter`); assertRef(row.locationMarkerId, locationMarkers, `${row.id}.location`); row.involvedCharacterIds.forEach(value => assertRef(value, characters, `${row.id}.character`)); row.involvedItemIds.forEach(value => assertRef(value, items, `${row.id}.item`)); if (!Number.isInteger(row.inWorldTime)) throw new Error(`${row.id}.calendar`); if (row.tension < 1 || row.tension > 5) throw new Error(`${row.id}.tension`) })
for (const eventRow of events) { const snaps = characterSnapshots.filter(row => row.eventId === eventRow.id); if (snaps.length !== eventRow.involvedCharacterIds.length) throw new Error(`${eventRow.id}.snapshot count`); if (new Set(snaps.map(row => row.statusNotes.toLowerCase())).size !== snaps.length) throw new Error(`${eventRow.id}.duplicate status`) }
mapLayers.forEach(row => assertRef(row.imageId, blobs, `${row.id}.image`)); locationMarkers.forEach(row => { assertRef(row.mapLayerId, mapLayers, `${row.id}.map`); assertRef(row.linkedMapLayerId, mapLayers, `${row.id}.linkedMap`); assertRef(row.imageId, blobs, `${row.id}.image`) }); characters.forEach(row => assertRef(row.portraitImageId, blobs, `${row.id}.portrait`)); items.forEach(row => assertRef(row.imageId, blobs, `${row.id}.image`))
const text = `${JSON.stringify(data, null, 2)}\n`
fs.writeFileSync('example/Twenty Thousand Leagues Under the Seas.pwk', text)
fs.writeFileSync('public/library/twenty-thousand-leagues-under-the-seas.pwk', text)
console.log(JSON.stringify({ chapters: chapters.length, events: events.length, characters: characters.length, snapshots: characterSnapshots.length, locations: locationMarkers.length, maps: mapLayers.length, items: items.length, relationships: relationships.length, lore: lorePages.length, factions: factions.length, knowledge: knowledgeFacts.length, bytes: Buffer.byteLength(text) }, null, 2))
